/* global __dirname */
// Local tooling script - embeds lightweight-charts' standalone build into the app, so the chart
// WebView renders from the bundle instead of downloading the library from a CDN on every open
// (slower first paint, and a blank chart on a weak or offline connection).
// Run after changing the lightweight-charts version: node scripts/bundle-chart-lib.js
const fs = require("fs");
const path = require("path");

// The package's "exports" map hides dist/ (and has no CJS entry), so read it from node_modules directly.
const pkgDir = fs.realpathSync(path.join(__dirname, "../node_modules/lightweight-charts"));
const pkg = JSON.parse(fs.readFileSync(path.join(pkgDir, "package.json"), "utf8"));
const source = fs.readFileSync(path.join(pkgDir, "dist/lightweight-charts.standalone.production.js"), "utf8");
// The source is inlined into a <script> tag, so it must not be able to close that tag early.
const safe = source.replace(/<\/script/gi, "<\\/script");

const out = path.join(__dirname, "../src/components/charts/chart-lib.generated.ts");
fs.writeFileSync(
  out,
  `// Generated by scripts/bundle-chart-lib.js from lightweight-charts ${pkg.version} - do not edit.\n` +
    `export const LIGHTWEIGHT_CHARTS_VERSION = ${JSON.stringify(pkg.version)};\n` +
    `export const LIGHTWEIGHT_CHARTS_SOURCE = ${JSON.stringify(safe)};\n`,
);
console.log(`Wrote ${path.relative(process.cwd(), out)} (lightweight-charts ${pkg.version}, ${(safe.length / 1024).toFixed(0)} KB)`);
